public class BindingDemonstration {

    static class Engine {
        // Static method demonstrates static binding (hiding, not overriding)
        public static void describe() {
            System.out.println("Standard Engine");
        }

        // Instance method participates in dynamic binding
        public void start() {
            System.out.println("Engine starting...");
        }
    }

    static class V8Engine extends Engine {
        // This shadows/hides the parent static method (Static Binding)
        public static void describe() {
            System.out.println("V8 Twin-Turbo Engine");
        }

        // This overrides the parent instance method (Dynamic Binding)
        @Override
        public void start() {
            System.out.println("V8 Engine roaring to life!");
        }
    }

    public static void main(String[] args) {
        Engine myEngine = new V8Engine();

        // Resolved at compile-time based on reference type (Engine)
        myEngine.describe(); 

        // Resolved at runtime based on object type (V8Engine)
        myEngine.start(); 
    }
}
